# Prepare a process directory generated by 'output <procdir> --vfold-with-tests'
# for the MadVFold tests (vfold/myLaunch.sh, vfold/myStepTest.sh...), so that it
# can be used like the hand-written <proc>_vfalt directories (created by the
# script copied in <proc>_vfalt/vfold/GEN_<proc>_vfalt.sh):
# - apply the post-processing of that script that does not need a launch
# - copy the cudacpp libraries and the MINT0/MINT1 test grids (for the -o
#   tests, see vfold/test/grids/README) from a reference directory
#   (default madvfold/DEV/<proc>_vfalt), if it exists
# The .gitignore and the test scripts of the vfold subdirectory are installed
# by the overlay (madvfold/overlay_test): they are not copied from the
# reference directory. The test grids are process-specific, so they are not
# in the overlay (for the moment they are taken from the reference directory).
# The code is built by the first run (./bin/generate_events, e.g. via vfold/myLaunch.sh).

set -e
set -o pipefail

if [ "$1" == "" ] || [ "$3" != "" ]; then
  echo "Usage:   $0 <procdir> [<refdir>]"
  echo "Example: $0 madvfold/DEV/eebbbb_vfgen madvfold/DEV/eebbbb_vfalt"
  exit 1
fi
mg5dir=$(cd $(dirname $0)/../..; pwd -P)
procdir=$(cd $1; pwd -P)
if [ "$2" != "" ]; then
  refdir=$(cd $2; pwd -P)
else
  proc=$(basename ${procdir}); proc=${proc%%_*} # e.g. eebbbb_vfgen -> eebbbb
  refdir=${mg5dir}/madvfold/DEV/${proc}_vfalt
  if [ ! -d ${refdir} ]; then refdir=; fi
fi
echo "INFO: setupVfoldTests.sh procdir=${procdir}"
echo "INFO: setupVfoldTests.sh refdir=${refdir}"
cd ${procdir}

# Post-processing from vfold/GEN_<proc>_vfalt.sh (see the comments there)
# - relative symlinks to the vendor libraries and relative paths in makefile_loop and make_opts
for f in vendor/CutTools/includects/mpmodule.mod vendor/CutTools/includects/libcts.a vendor/IREGI/src/libiregi.a; do
  ln -sf $(realpath --relative-to=lib ${mg5dir}/${f}) lib/
done
sed -i "s|${mg5dir}/HEPTools/include$|\$(LIBDIR)|" SubProcesses/makefile_loop
sed -i "s|MG5AMC_VERSION=$|MG5AMC_VERSION=5.|" Source/make_opts
sed -i "s|PYTHIA8_PATH=.*|PYTHIA8_PATH=this_variable_is_not_used|" Source/make_opts
sed -i "s|\['PYTHIA8_PATH'\]=self|['PYTHIA8_PATH']='this_variable_is_not_used' # self|" bin/internal/common_run_interface.py
# (make_opts is used to link in SubProcesses/P*, makefile_loop to build in SubProcesses/P*/V*)
sed -i "s|${mg5dir}|../$(realpath --relative-to=SubProcesses ${mg5dir})|g" Source/make_opts
sed -i "s|${mg5dir}|../../$(realpath --relative-to=SubProcesses ${mg5dir})|g" SubProcesses/makefile_loop
# - move away shower_card.dat, remove driver_mintFO.f and py.py
if [ -f Cards/shower_card.dat ]; then mv Cards/shower_card.dat Cards/.shower_card.dat; fi
# - move away plot_card.dat, as the first launch (with -p) does
if [ -f Cards/plot_card.dat ]; then mv Cards/plot_card.dat Cards/.plot_card.dat; fi
sed -i "s|${mg5dir}|<mg5dir>|g" Cards/.shower_card.dat
rm -f SubProcesses/driver_mintFO.f
rm -f SubProcesses/*/*/py.py
# - relative paths and no html opening in amcatnlo_configuration.txt
sed -i "s|pythia8_path = .*|pythia8_path = ./HEPTools/pythia8|" Cards/amcatnlo_configuration.txt
sed -i "s|hepmc_path = .*|hepmc_path = ./HEPTools/hepmc|" Cards/amcatnlo_configuration.txt
sed -i "s|# automatic_html_opening = True|automatic_html_opening = False|" Cards/amcatnlo_configuration.txt

# Test material from the reference directory
if [ "${refdir}" == "" ]; then
  echo "WARNING! No reference directory: cudacpp libraries and test grids not copied"
  exit 0
fi
# - cudacpp libraries for mode C (see vfold/copyCudacppLibs.sh)
if [ -d ${refdir}/lib/cudacpp ]; then
  command rm -rf lib/cudacpp
  command cp -dpr ${refdir}/lib/cudacpp lib/cudacpp
fi
# - MINT0/MINT1 grids for the -o tests (see vfold/test/grids/README)
if [ -d ${refdir}/vfold/test/grids ]; then
  command rm -rf vfold/test/grids
  mkdir -p vfold/test
  command cp -dpr ${refdir}/vfold/test/grids vfold/test/grids
fi
echo "INFO: setupVfoldTests.sh completed"
